def fmt(x: float, digits: int = 6) -> str: return f"{x:.{digits}g}"
def page(title: str, body: str, css: str = CSS) -> str: return f"<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>{html.escape(title)}</title><script id='MathJax-script' async src='https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js'></script><style>{css}</style></head><body>{body}</body></html>"
def header(title: str, subtitle: str) -> str: return f"<header><div><h1>{html.escape(title)}</h1><p>{html.escape(subtitle)}</p></div></header>"
def bullets(items: list[str]) -> str: return "<ul>" + "".join(f"<li>{html.escape(x)}</li>" for x in items) + "</ul>"

def check(i: int) -> tuple[str, str]:
    if i == 1: return "R has five required fields: claim, data, code, environment, and provenance.", "A missing field is a reproducibility defect, not merely a documentation preference."
    if i == 2: return "A frozen screen retaining 6 of 18 records has fraction 6/18 = 0.333333.", "This describes the screen, not the quality of the literature."
    if i == 3: return "Q records service, ADQL, columns, constraints, release, and timestamp; omitting one changes provenance.", "Query provenance is the research equivalent of an instrument configuration."
    if i == 4: return f"exp[-0.5(0.8/0.3)^2] = {fmt(math.exp(-0.5*(0.8/0.3)**2))}.", "This is not a posterior match probability until background density and competing candidates are included."
    if i == 5: return f"For d=1/p, d=0.5 kpc and sigma_d≈{fmt(0.05/(2.0**2))} kpc; the stated zero point gives d={fmt(1/(2.0-GAIA_ZERO_POINT_MAS))} kpc.", "The propagation is local; the offset is shared and is not independent noise."
    if i == 6: return f"BIC_2={fmt(2*math.log(20)+18)}, BIC_4={fmt(4*math.log(20)+12)}; delta BIC={fmt(2*math.log(20)+18-(4*math.log(20)+12))}.", "BIC does not replace residual diagnosis or scientific interpretation."
    if i == 7: return "A deterministic function with a fixed seed and invariant test exposes hidden state.", "Reproducibility is testable when expected inputs and outputs are explicit."
    if i == 8: return "A log-log slope is d log(y)/d log(x); changing axes changes visual sensitivity, not the data.", "A plot must disclose transformations, units, limits, and uncertainty encodings."
    if i == 9: return "A feasible 10-hour plan is 7.0 h integration + 1.0 h calibration + 1.0 h overhead + 1.0 h contingency.", "This is a planning example, not an observatory performance claim."
    if i == 10: return "Authorship requires substantial contribution and accountability; a citation or acknowledgment alone does not automatically confer authorship.", "Local institutional policy must be checked before use."
    if i == 11: return "MAST serves mission products, Gaia astrometric catalogs, SDSS imaging/spectroscopy, and Exoplanet Archive curated tables; product scope is the discriminant.", "Archive choice is part of scientific design."
    if i == 12: return f"1-(1-0.05)^20 = {fmt(1-0.95**20)}.", "The calculation assumes independent tests; undisclosed multiplicity still matters."
    if i == 13: return "A 90-second talk needs one question, one evidence figure, one uncertainty statement, and one consequence.", "Compression should remove redundancy, not validity-defining caveats."
    if i == 14: return "A decision matrix makes science, feasibility, access, risk, and reproducibility scores auditable.", "The best project is one whose failure modes are informative."
    return "A reviewer traces the claim through sample, method, uncertainty, ethics, and provenance.", "Review tests whether another researcher could reproduce and challenge the conclusion."

